[InitializeOnLoad]public static class FinalCitySignsExpand{
const string Dir="Assets/Scenes/Oasis/CityBuildingSigns",Group="City Building Signs - Shared Atlas";
static BindingFlags F=BindingFlags.Static|BindingFlags.NonPublic;static Type T=typeof(FinalCitySigns),BT=T.GetNestedType("B",BindingFlags.NonPublic),ST=T.GetNestedType("Site",BindingFlags.NonPublic);
static object C(string n,params object[] a)=>T.GetMethod(n,F).Invoke(null,a);static V Get<V>(object o,string n)=>(V)o.GetType().GetField(n).GetValue(o);static void Set(object o,string n,object v)=>o.GetType().GetField(n).SetValue(o,v);
class Panel{public Vector3 p,n;public float w,h;public string owner;}
static List<Panel> panels=new List<Panel>();static List<Panel> created=new List<Panel>();static List<GameObject> newObjects=new List<GameObject>();static List<string> records=new List<string>();static int added,longs,banners,full;
static object Site(object g,Vector3 p,Vector3 n,float w,float h,int tile){var s=Activator.CreateInstance(ST,true);Set(s,"g",g);Set(s,"p",p);Set(s,"n",n);Set(s,"w",w);Set(s,"h",h);Set(s,"art",tile);return s;}
static void Box(object b,Vector3 p,Vector3 right,Vector3 up,Vector3 n,float w,float h,float depth,Color color)=>BT.GetMethod("Box").Invoke(b,new object[]{p,right,up,n,w,h,depth,color});
static bool Free(Vector3 p,Vector3 n,float w,float h){var right=Vector3.Cross(Vector3.up,n);return !panels.Any(s=>Mathf.Abs(Vector3.Dot(s.n,n))>.95f&&Mathf.Abs(Vector3.Dot(s.p-p,n))<1.6f&&Mathf.Abs(Vector3.Dot(s.p-p,right))<(s.w+w)*.5f+.22f&&Mathf.Abs(s.p.y-p.y)<(s.h+h)*.5f+.22f);}
static bool Support(object g,Vector3 p,Vector3 n,float w,float h,out float advance){advance=0;var right=Vector3.Cross(Vector3.up,n);for(int y=0;y<=20;y++)foreach(float x in new[]{-.5f,-.25f,0,.25f,.5f}){var q=p+right*x*w+Vector3.up*((y/20f-.5f)*h);object[] a={g,q+n*3,-n,Vector3.zero,Vector3.zero};if(!(bool)C("Hit",a))return false;var hit=(Vector3)a[3];var normal=(Vector3)a[4];float d=Vector3.Dot(hit-p,n);if(d<-.55f||d>1.2f||Mathf.Abs(Vector3.Dot(normal,n))<.88f)return false;advance=Mathf.Max(advance,d+.13f);}return true;}
static bool View(Array all,Vector3[] roads,Vector3 p,Vector3 n,out Vector3 camera){object[] a={all,roads,p,n,Vector3.zero};bool okay=(bool)typeof(FinalCitySignsFinish).GetMethod("RoadView",F).Invoke(null,a);camera=(Vector3)a[4];return okay;}
static void Emit(object builder,Transform group,Material mat,Vector3 origin,string name,Panel panel){int number=group.childCount;var mesh=(Mesh)BT.GetMethod("Mesh").Invoke(builder,new object[]{name,origin});var uv=mesh.uv;var colors=mesh.colors;for(int i=0;i<mesh.vertexCount;i+=4){if(colors[i].a<.4f||colors[i].a>.6f)continue;float sum=uv[i].x+uv[i+2].x;for(int j=i;j<i+4;j++)uv[j].x=sum-uv[j].x;}mesh.uv=uv;AssetDatabase.CreateAsset(mesh,AssetDatabase.GenerateUniqueAssetPath(Dir+"/Meshes/Signs-"+number.ToString("000")+".asset"));var go=new GameObject(name);go.transform.SetParent(group,false);go.transform.position=origin;go.AddComponent<MeshFilter>().sharedMesh=mesh;var r=go.AddComponent<MeshRenderer>();r.sharedMaterial=mat;r.shadowCastingMode=ShadowCastingMode.Off;r.receiveShadows=false;r.lightProbeUsage=LightProbeUsage.Off;r.reflectionProbeUsage=ReflectionProbeUsage.Off;var lod=go.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.045f,new Renderer[]{r})});lod.RecalculateBounds();lod.size=Mathf.Clamp(lod.size,8,24);GameObjectUtility.SetStaticEditorFlags(go,StaticEditorFlags.BatchingStatic|StaticEditorFlags.OccludeeStatic);PrefabUtility.SaveAsPrefabAssetAndConnect(go,AssetDatabase.GenerateUniqueAssetPath(Dir+"/Prefabs/Additional Sign "+number.ToString("000")+".prefab"),InteractionMode.AutomatedAction);panels.Add(panel);created.Add(panel);newObjects.Add(go);added++;records.Add(name+", "+origin+", "+panel.w+" x "+panel.h);}
static void Column(object g,Panel s,Transform group,Material mat,int seed){var b=Activator.CreateInstance(BT,true);int pieces=Mathf.Max(1,Mathf.RoundToInt(s.h/(s.w*2.65f)));float height=s.h/pieces;for(int i=0;i<pieces;i++){var p=s.p+Vector3.up*((i+.5f)*height-s.h*.5f);var site=Site(g,p,s.n,s.w,height-.10f,12+(seed+i)%8);BT.GetMethod("Board").Invoke(b,new object[]{site,false});}
var right=Vector3.Cross(Vector3.up,s.n);var color=new[]{new Color(.12f,.7f,.9f,1),new Color(1,.6f,.17f,1),new Color(.8f,.12f,.6f,1)}[seed%3];foreach(float side in new[]{-1f,1f})Box(b,s.p+right*side*(s.w*.5f+.13f),right,Vector3.up,s.n,.075f,s.h,.055f,color);Emit(b,group,mat,s.p,"Long facade column "+group.childCount.ToString("000")+" - "+s.owner,s);longs++;}
static void Banner(object g,Vector3 p,Vector3 n,float w,float h,Transform group,Material mat,string name,int seed){var b=Activator.CreateInstance(BT,true);var right=Vector3.Cross(Vector3.up,n);int pieces=3;float unit=w/pieces;for(int i=0;i<pieces;i++){var center=p+right*((i+.5f)*unit-w*.5f);var site=Site(g,center,n,unit-.10f,h,20+(seed+i)%4);BT.GetMethod("Board").Invoke(b,new object[]{site,false});var uv=Get<List<Vector2>>(b,"uv");int start=uv.Count-4;Vector4 rect=i==0?new Vector4(18/1254f,1-174/1254f,280/1254f,43/1254f):i==1?new Vector4(967/1254f,1-93/1254f,274/1254f,52/1254f):new Vector4(644/1254f,1-1192/1254f,283/1254f,63/1254f);uv[start]=new Vector2(rect.x,rect.y);uv[start+1]=new Vector2(rect.x+rect.z,rect.y);uv[start+2]=new Vector2(rect.x+rect.z,rect.y+rect.w);uv[start+3]=new Vector2(rect.x,rect.y+rect.w);}var s=new Panel{p=p,n=n,w=w,h=h,owner=name};Emit(b,group,mat,p,"Bridge signage "+group.childCount.ToString("000")+" - "+name,s);banners++;}
static void Photo(Scene scene,Vector3 p,Vector3 target,string name)=>typeof(FinalPNGCityDetails).GetMethod("Capture",F).Invoke(null,new object[]{scene,p,target,name});
static FinalCitySignsExpand(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("FinalCitySignsExpand.request")||EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode)return;File.Delete("FinalCitySignsExpand.request");Run();}
static void Run(){var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var group=scene.GetRootGameObjects().Single(g=>g.name==Group);if(group.transform.childCount>=600)throw new Exception("Expansion already installed");string backup="FinalEnvironmentRoadBackup/SignExpansion-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");Directory.CreateDirectory(backup);EditorSceneManager.SaveScene(scene,backup+"/Before.unity",true);File.Copy(Dir+"/City Building Signs.prefab",backup+"/Before.prefab");var mat=AssetDatabase.LoadAssetAtPath<Material>(Dir+"/City Shared Sign Atlas.mat");var renderers=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).ToArray();var native=renderers.Where(r=>r.sharedMaterials.Any(m=>m&&m.name.StartsWith("Building"))&&r.GetComponent<MeshFilter>()&&r.enabled&&r.gameObject.activeInHierarchy&&r.bounds.size.y>18&&r.bounds.size.y<180&&r.bounds.size.x>7&&r.bounds.size.z>7).ToArray();var gt=T.GetNestedType("Geo",BindingFlags.NonPublic);var all=Array.CreateInstance(gt,native.Length);for(int i=0;i<native.Length;i++)all.SetValue(C("Read",native[i]),i);var controller=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();var roads=controller.streetLightPositions;
foreach(var f in group.GetComponentsInChildren<MeshFilter>()){var m=f.sharedMesh;var p=m.vertices;var c=m.colors;for(int i=0;i<p.Length;i+=4){if(c[i].a<.4f||c[i].a>.6f)continue;panels.Add(new Panel{p=f.transform.TransformPoint((p[i]+p[i+1]+p[i+2]+p[i+3])*.25f),n=f.transform.TransformDirection(Vector3.Cross(p[i+1]-p[i],p[i+3]-p[i]).normalized),w=Vector3.Distance(p[i],p[i+1]),h=Vector3.Distance(p[i],p[i+3]),owner=f.name});}}
var track=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");foreach(var module in track.GetComponentsInChildren<Transform>(true).Where(t=>t.name.StartsWith("Sunken Underpass "))){var roof=module.GetComponentsInChildren<BoxCollider>().Single(c=>c.name=="Roof collision");var bounds=roof.bounds;bool alongX=bounds.size.x>bounds.size.z;var direction=alongX?Vector3.right:Vector3.forward;var r=module.GetComponentsInChildren<MeshRenderer>().Single(r=>r.name=="Concrete walls roof and curbs");var g=C("Read",r);float length=alongX?bounds.size.x:bounds.size.z,width=alongX?bounds.size.z:bounds.size.x;foreach(int end in new[]{-1,1}){var n=direction*end;var p=bounds.center+n*(length*.5f+.14f);float h=Mathf.Min(.52f,bounds.size.y-.22f),w=Mathf.Min(17,width*.66f);if(Support(g,p-n*.14f,n,w,h,out float advance)){p+=n*Mathf.Max(0,advance-.14f);Banner(g,p,n,w,h,group.transform,mat,module.name+" entrance "+end,banners);}}}
foreach(var r in renderers.Where(r=>r.GetComponent<MeshFilter>()&&r.enabled&&!r.transform.IsChildOf(group.transform)&&r.bounds.max.y>32&&r.bounds.size.y>.2f&&r.bounds.size.y<24&&Mathf.Max(r.bounds.size.x,r.bounds.size.z)>18&&Mathf.Max(r.bounds.size.x,r.bounds.size.z)<160&&Mathf.Min(r.bounds.size.x,r.bounds.size.z)<9).Take(100)){if(banners>=10)break;var g=C("Read",r);var p=Get<Vector3[]>(g,"p");var ids=Get<int[]>(g,"ids");for(int j=0;j<ids.Length;j+=3){var a=p[ids[j]];var b=p[ids[j+1]];var d=p[ids[j+2]];var cross=Vector3.Cross(b-a,d-a);if(cross.magnitude<8||Mathf.Abs(cross.normalized.y)>.15f)continue;var center=(a+b+d)/3;if(center.y<32)continue;var n=cross.normalized;if(Vector3.Dot(center-r.bounds.center,n)<0)n=-n;float w=5.2f,h=.55f;if(!Free(center,n,w,h)||!Support(g,center,n,w,h,out float advance))continue;Banner(g,center+n*advance,n,w,h,group.transform,mat,r.name,banners);break;}}
var done=new HashSet<object>();for(int pass=0;pass<3&&group.transform.childCount<600;pass++){foreach(var g in all.Cast<object>().OrderBy(g=>Mathf.Abs(Get<Bounds>(g,"bounds").size.y-38))){if(group.transform.childCount>=600)break;if(pass==0&&done.Contains(g))continue;var bounds=Get<Bounds>(g,"bounds");var r=Get<MeshRenderer>(g,"r");var directions=(Vector3[])C("Directions",g,roads);bool placed=false;
foreach(var n in directions.Take(6)){float span=Mathf.Abs(n.x)*bounds.size.z+Mathf.Abs(n.z)*bounds.size.x;float w=Mathf.Clamp(span*.08f,1.6f,2.6f);float h=Mathf.Clamp(bounds.size.y*(pass==0?.78f:pass==1?.52f:.38f),pass==0?12:8,48);if(h>bounds.size.y-5)h=bounds.size.y-5;var right=Vector3.Cross(Vector3.up,n);foreach(float offset in new[]{-.39f,.39f,-.29f,.29f,-.18f,.18f}){var target=bounds.center+right*span*offset;target.y=bounds.min.y+4.1f+h*.5f;object[] a={g,target+n*400,-n,Vector3.zero,Vector3.zero};if(!(bool)C("Hit",a))continue;var p=(Vector3)a[3];if(!Free(p,n,w,h)||!Support(g,p,n,w,h,out float advance))continue;p+=n*advance;if(!Free(p,n,w,h)||!View(all,roads,p,n,out _))continue;var site=new Panel{p=p,n=n,w=w,h=h,owner=r.name};Column(g,site,group.transform,mat,longs+7);done.Add(g);if(pass==0)full++;placed=true;break;}if(placed)break;}
if(added%25==0)File.WriteAllText("FinalEnvironmentRoadReview/SignExpansionProgress.txt","placements="+group.transform.childCount+"; extra long columns="+longs+"; bridge banners="+banners);}}
if(group.transform.childCount!=600)throw new Exception("Could only find supported non-overlapping placements="+group.transform.childCount);AssetDatabase.SaveAssets();PrefabUtility.SaveAsPrefabAssetAndConnect(group,Dir+"/City Building Signs.prefab",InteractionMode.AutomatedAction);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
bool night=controller.IsNight;try{int shots=0;foreach(var s in created.Where(s=>s.h>10).OrderBy(s=>Mathf.Abs(s.h-30)).Take(50)){if(shots>=3)break;if(!View(all,roads,s.p,s.n,out var camera))continue;shots++;controller.ApplyDay();Photo(scene,camera,s.p,"Long-Signs-Day-"+shots);controller.ApplyNight();Photo(scene,camera,s.p,"Long-Signs-Night-"+shots);}foreach(var s in created.Where(s=>s.owner.StartsWith("Sunken Underpass ")).Take(4)){controller.ApplyDay();var camera=s.p+s.n*32-Vector3.up*3;Photo(scene,camera,s.p,"Bridge-Signs-"+s.owner.Replace(" ","_"));}}finally{if(night)controller.ApplyNight();else controller.ApplyDay();}
var rs=group.GetComponentsInChildren<MeshRenderer>(true);var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(Dir+"/City Building Signs.prefab");if(rs.Length!=600||prefab.GetComponentsInChildren<MeshRenderer>(true).Length!=600)throw new Exception("Scene/prefab counts mismatch");if(rs.Any(r=>r.sharedMaterial!=mat))throw new Exception("Not one shared material");int errors=ShaderUtil.GetShaderMessages(mat.shader).Count(v=>v.severity.ToString()=="Error");if(errors>0)throw new Exception("Shader errors="+errors);log.AppendLine("SUCCESS total sign-prefab placements=600; added="+added+"; new long columns="+longs+"; facade-height columns="+full+"; bridge banners="+banners+"; total triangles="+rs.Sum(r=>(int)r.GetComponent<MeshFilter>().sharedMesh.GetIndexCount(0)/3)+"; one existing atlas/material; LOD and static batching retained; no new lights/colliders; shader errors=0; scene and master prefab saved; backup="+backup);File.WriteAllLines("FinalEnvironmentRoadReview/SignExpansionPlacements.txt",records);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/SignExpansionReport.txt",log.ToString());}}
